<?php
/**
 * Generates the WordPress.org directory icons and banners.
 *
 * Drawn programmatically with GD rather than sourced from anywhere, so the
 * artwork is original to this plugin and unambiguously GPL-compatible. SPEC
 * section 10.1 requires every bundled asset to be GPL-compatible with its source
 * documented, and "generated by this script" is the clearest provenance there is.
 *
 * The design is the plugin's own subject matter: a sidebar with grouped, indented
 * rows and one collapsed group, which is what the plugin actually does.
 *
 * Usage: php bin/build-assets.php
 */

if ( ! extension_loaded( 'gd' ) ) {
	echo "The gd extension is required to generate assets.\n";
	exit( 1 );
}

$out = dirname( __DIR__ ) . '/.wordpress-org';

if ( ! is_dir( $out ) ) {
	mkdir( $out, 0755, true );
}

/**
 * Allocates a colour from a hex string.
 *
 * @param resource|GdImage $im  Image handle.
 * @param string           $hex Six-digit hex colour.
 * @return int
 */
function hex( $im, string $hex ): int {
	return imagecolorallocate(
		$im,
		(int) hexdec( substr( $hex, 0, 2 ) ),
		(int) hexdec( substr( $hex, 2, 2 ) ),
		(int) hexdec( substr( $hex, 4, 2 ) )
	);
}

/**
 * Draws a rounded rectangle.
 *
 * @param resource|GdImage $im     Image handle.
 * @param int              $x      Left.
 * @param int              $y      Top.
 * @param int              $w      Width.
 * @param int              $h      Height.
 * @param int              $radius Corner radius.
 * @param int              $colour Allocated colour.
 * @return void
 */
function rounded( $im, int $x, int $y, int $w, int $h, int $radius, int $colour ): void {
	$radius = (int) min( $radius, floor( $h / 2 ), floor( $w / 2 ) );

	imagefilledrectangle( $im, $x + $radius, $y, $x + $w - $radius, $y + $h, $colour );
	imagefilledrectangle( $im, $x, $y + $radius, $x + $w, $y + $h - $radius, $colour );

	$d = $radius * 2;
	imagefilledellipse( $im, $x + $radius, $y + $radius, $d, $d, $colour );
	imagefilledellipse( $im, $x + $w - $radius, $y + $radius, $d, $d, $colour );
	imagefilledellipse( $im, $x + $radius, $y + $h - $radius, $d, $d, $colour );
	imagefilledellipse( $im, $x + $w - $radius, $y + $h - $radius, $d, $d, $colour );
}

/**
 * Draws the sidebar motif: grouped rows, one group collapsed.
 *
 * @param resource|GdImage $im    Image handle.
 * @param int              $x     Left edge of the motif.
 * @param int              $y     Top edge of the motif.
 * @param float            $scale Scale factor, 1.0 being the 256px icon.
 * @return void
 */
function motif( $im, int $x, int $y, float $scale ): void {
	$header = hex( $im, 'ffffff' );
	$row    = hex( $im, '8fb8dd' );
	$accent = hex( $im, 'ffd166' );

	$unit    = 14 * $scale;
	$radius  = (int) max( 2, 3 * $scale );
	$row_h   = (int) max( 4, 9 * $scale );
	$gap     = (int) max( 3, 6 * $scale );
	$indent  = (int) ( 12 * $scale );
	$width   = (int) ( 120 * $scale );
	$cursor  = $y;

	// Group one: header plus two members, expanded.
	rounded( $im, $x, $cursor, (int) ( $width * 0.62 ), $row_h, $radius, $header );
	$cursor += $row_h + $gap;

	for ( $i = 0; $i < 2; $i++ ) {
		rounded( $im, $x + $indent, $cursor, (int) ( $width * 0.78 ), $row_h, $radius, $row );
		$cursor += $row_h + $gap;
	}

	$cursor += (int) ( $gap * 0.6 );

	// Group two: header plus three members, expanded, with one highlighted so the
	// eye has somewhere to land.
	rounded( $im, $x, $cursor, (int) ( $width * 0.5 ), $row_h, $radius, $header );
	$cursor += $row_h + $gap;

	for ( $i = 0; $i < 3; $i++ ) {
		rounded(
			$im,
			$x + $indent,
			$cursor,
			(int) ( $width * ( 1 === $i ? 0.66 : 0.86 ) ),
			$row_h,
			$radius,
			1 === $i ? $accent : $row
		);
		$cursor += $row_h + $gap;
	}

	$cursor += (int) ( $gap * 0.6 );

	// Group three: header only, collapsed. This is the whole point of the plugin,
	// so it is the last thing the eye reads.
	rounded( $im, $x, $cursor, (int) ( $width * 0.56 ), $row_h, $radius, $header );
}

/**
 * Fills an image with a vertical gradient.
 *
 * @param resource|GdImage $im   Image handle.
 * @param int              $w    Width.
 * @param int              $h    Height.
 * @param string           $from Top colour.
 * @param string           $to   Bottom colour.
 * @return void
 */
function gradient( $im, int $w, int $h, string $from, string $to ): void {
	$fr = array( hexdec( substr( $from, 0, 2 ) ), hexdec( substr( $from, 2, 2 ) ), hexdec( substr( $from, 4, 2 ) ) );
	$tr = array( hexdec( substr( $to, 0, 2 ) ), hexdec( substr( $to, 2, 2 ) ), hexdec( substr( $to, 4, 2 ) ) );

	for ( $row = 0; $row < $h; $row++ ) {
		$ratio  = $h > 1 ? $row / ( $h - 1 ) : 0;
		$colour = imagecolorallocate(
			$im,
			(int) round( $fr[0] + ( $tr[0] - $fr[0] ) * $ratio ),
			(int) round( $fr[1] + ( $tr[1] - $fr[1] ) * $ratio ),
			(int) round( $fr[2] + ( $tr[2] - $fr[2] ) * $ratio )
		);

		imageline( $im, 0, $row, $w, $row, $colour );
	}
}

/**
 * Writes a PNG and reports it.
 *
 * @param resource|GdImage $im   Image handle.
 * @param string           $path Destination.
 * @return void
 */
function save( $im, string $path ): void {
	imagepng( $im, $path, 9 );
	imagedestroy( $im );

	printf( "  %-24s %6.1f KB\n", basename( $path ), filesize( $path ) / 1024 );
}

echo "Icons:\n";

foreach ( array( 128, 256 ) as $size ) {
	$im = imagecreatetruecolor( $size, $size );
	imageantialias( $im, true );

	gradient( $im, $size, $size, '1d3d5c', '2b6cb0' );

	$scale = $size / 256;
	motif( $im, (int) ( 64 * $scale ), (int) ( 52 * $scale ), $scale * 1.05 );

	save( $im, "{$out}/icon-{$size}x{$size}.png" );
}

echo "Banners:\n";

foreach ( array( array( 772, 250 ), array( 1544, 500 ) ) as $dimensions ) {
	list( $w, $h ) = $dimensions;

	$im = imagecreatetruecolor( $w, $h );
	imageantialias( $im, true );

	gradient( $im, $w, $h, '18324a', '2b6cb0' );

	$scale = $h / 250;

	// The motif sits on the right, leaving the left clear for the title the
	// directory renders over the banner.
	motif( $im, (int) ( $w - 210 * $scale ), (int) ( 34 * $scale ), $scale * 1.15 );

	// A restrained accent rule along the bottom edge.
	imagefilledrectangle( $im, 0, $h - (int) ( 4 * $scale ), $w, $h, hex( $im, 'ffd166' ) );

	save( $im, "{$out}/banner-{$w}x{$h}.png" );
}

echo "\nAll assets generated by this script. Original work, GPLv2 or later.\n";
